import type { Metadata } from "next";
import Image from "next/image";
import { Homemade_Apple } from "next/font/google";
import WineStains from "./WineStains";

// The one hand-written line on the page. next/font self-hosts the file at
// build time, so no request leaves for Google when the page is read.
const pen = Homemade_Apple({
  weight: "400",
  subsets: ["latin"],
  display: "swap",
  variable: "--manifesto-pen",
});

// An unlinked page: not in the sitemap, not in navigation, not indexed.
export const metadata: Metadata = {
  title: "The Wine Bastard Manifesto",
  description: "What a Wine Bastard believes about wine, knowledge, memory and time.",
  robots: { index: false, follow: false },
};

export default function BastardPage() {
  return (
    <article className={`manifesto ${pen.variable}`} aria-labelledby="manifesto-title">
      <div className="manifesto-sheet">
        <WineStains />
        <h1 id="manifesto-title" className="manifesto-title-hidden">The Wine Bastard Manifesto</h1>

        <div className="manifesto-verse">
          <div className="manifesto-stamp-row">
            <Image
              className="manifesto-stamp"
              src="/brand/wine-bastard-stamp.svg"
              alt=""
              width={800}
              height={368}
              unoptimized
            />
          </div>

          <p className="manifesto-carries">
            Every bottle carries
            <span>a place,</span>
            <span>a maker,</span>
            <span>a history</span>
            <span>and a future.</span>
          </p>

          <p>What it means is yours.</p>

          <p>
            Know more.
            <br />
            Make no one feel less.
          </p>

          <p>
            A famous bottle can disappoint.
            <br />
            A humble one can stop the room.
            <br />
            You may say so.
          </p>

          <p>
            Wine changes in the bottle.
            <br />
            What we know should not stand still.
          </p>

          <p>
            The machine minds the cellar.
            <br />
            You mind the moments.
          </p>

          <p>
            Know where it came from.
            <br />
            Know where you put it.
            <br />
            Know when to leave it there.
          </p>

          <p>
            Some evenings need remembering.
            <br />
            Write them down before they improve with age.
          </p>

          <p className="manifesto-margin">Margins are for writing in.</p>

          <p>Your cellar is nobody else&rsquo;s business.</p>

          <p className="manifesto-close">Enjoy it mightily.</p>
        </div>
      </div>
    </article>
  );
}
@import "tailwindcss";

:root {
  /* Warm papyrus aesthetic is light-only — never follow the OS dark preference */
  color-scheme: light;

  /* Atlas Canvas (Papyrus/Sepia) */
  --atlas-bg: #fdf6e3;
  --atlas-card: #eee8d5;
  --atlas-card-stroke: #CEC4B2;
  --atlas-text: #3D3528;
  --atlas-text-secondary: #6B614E;
  /* Muted text: 4.77:1 on --atlas-bg (WCAG AA for the small date/colophon sizes; was #8A7D68 at 3.73:1) */
  --atlas-text-placeholder: #786C58;
  --atlas-separator: #B8AC94;
  --atlas-tint: #8B7355;
  /* Link text: the tint darkened to pass WCAG AA (4.88:1 on --atlas-bg; the tint is 4.16:1) */
  --atlas-link: #806847;
  --atlas-destructive: #A85040;

  /* Chrome — warm, matching canvas */
  --chrome-bg: #fdf6e3;

  /* Typography */
  --font-sans: 'Avenir Next', 'Avenir', 'Nunito Sans', 'Trebuchet MS', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --background: var(--atlas-bg);
  --foreground: var(--atlas-text);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  /* let the full-bleed hero map extend to the viewport edges without
     introducing a horizontal scrollbar (clip doesn't break sticky header) */
  overflow-x: clip;
  /* fill the viewport so the footer is pinned to the bottom and the hero
     canvas grows to absorb any slack (sticky-footer layout) */
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* the canvas between header and footer grows to fill leftover height;
   any extra space lands under the hero content, above the footer */
main {
  flex: 1 0 auto;
  display: flex;
  flex-direction: column;
}

/* Keyboard focus — visible ring on all interactive elements */
a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--atlas-tint);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Blog post list — hover feedback */
.blog-post-link {
  transition: background 0.15s ease;
}

.blog-post-link:hover {
  background: var(--atlas-card);
}

/* Article prose styling */
.prose h1 {
  font-weight: 600;
  font-size: 2rem;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--atlas-text);
  margin-bottom: 0.5rem;
}

.prose h2 {
  font-weight: 600;
  font-size: 1.4rem;
  letter-spacing: -0.01em;
  line-height: 1.3;
  color: var(--atlas-text);
  margin-top: 2.5rem;
  margin-bottom: 0.75rem;
}

.prose h3 {
  font-weight: 600;
  font-size: 1.15rem;
  color: var(--atlas-text);
  margin-top: 2rem;
  margin-bottom: 0.5rem;
}

.prose p {
  font-size: 1.05rem;
  line-height: 1.75;
  color: var(--atlas-text-secondary);
  margin-bottom: 1.5rem;
}

.prose blockquote {
  border-left: 3px solid var(--atlas-tint);
  padding-left: 1.25rem;
  margin: 2rem 0;
  font-style: italic;
  color: var(--atlas-text-secondary);
}

.prose ul, .prose ol {
  padding-left: 1.5rem;
  margin-bottom: 1.5rem;
  color: var(--atlas-text-secondary);
}

.prose li {
  line-height: 1.75;
  margin-bottom: 0.5rem;
}

.prose a,
.text-link {
  color: var(--atlas-link);
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: color 0.15s ease;
}

.prose a:hover,
.text-link:hover {
  color: var(--atlas-text);
}

.prose hr {
  border: none;
  border-top: 1px solid var(--atlas-separator);
  margin: 2.5rem 0;
}

/* The Wine Bastard Manifesto (/bastard): a pocket manifesto. A small printed
   broadside someone folded into thirds, carried, read over wine and wrote on.
   Three kinds of imperfection and no more: a sheet with edges, grain and two
   pocket folds; a large oxblood stamp that skipped and blotted; human evidence,
   one broken wine ring and one line in pen. The type itself stays crisp: the
   thing was printed, then life happened to the paper. */
.manifesto {
  --manifesto-serif: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif;
  --manifesto-ink: #3d3528;
  --manifesto-oxblood: #6e1522;
  --manifesto-wine: #6b1e2e;
  --manifesto-pen-ink: #2a2f45;
  --manifesto-paper: #fffaec;
  display: flex;
  justify-content: center;
  padding: clamp(1.5rem, 6vh, 4.5rem) 12px clamp(3rem, 8vh, 5rem);
  color: var(--manifesto-ink);
}

/* The sheet is the object. A shade whiter than the site, half a degree off
   true, a real shadow, and overflow clipped so the stamp and the ring are
   cropped by the paper's edge rather than the viewport's. */
.manifesto .manifesto-sheet {
  position: relative;
  width: min(100%, 42rem);
  background-color: var(--manifesto-paper);
  transform: rotate(-0.45deg);
  box-shadow:
    0 0 0 1px rgba(61, 53, 40, 0.07),
    0 1px 2px rgba(61, 53, 40, 0.16),
    0 18px 40px -20px rgba(61, 53, 40, 0.45);
  overflow: hidden;
  padding: clamp(2.25rem, 7vh, 4.5rem) 0 clamp(3rem, 9vh, 5.5rem);
}

/* Two pocket folds, a letter fold not quite in thirds: a catch-light along
   the crease, a soft shadow band below it, and the middle panel a shade
   darker where it sat inside. Tilted a touch so they are not ruled lines. */
.manifesto .manifesto-sheet::before {
  content: "";
  position: absolute;
  inset: -4% -2%;
  z-index: 0;
  pointer-events: none;
  transform: rotate(0.6deg);
  background:
    linear-gradient(180deg,
      transparent calc(35% - 1px),
      rgba(255, 255, 255, 0.7) calc(35% - 1px),
      rgba(255, 255, 255, 0.7) 35%,
      rgba(61, 53, 40, 0.09) 35%,
      rgba(61, 53, 40, 0.05) calc(35% + 6px),
      rgba(61, 53, 40, 0) calc(35% + 22px),
      transparent calc(68% - 1px),
      rgba(255, 255, 255, 0.7) calc(68% - 1px),
      rgba(255, 255, 255, 0.7) 68%,
      rgba(61, 53, 40, 0.08) 68%,
      rgba(61, 53, 40, 0.04) calc(68% + 6px),
      rgba(61, 53, 40, 0) calc(68% + 24px),
      transparent 100%),
    linear-gradient(180deg,
      rgba(61, 53, 40, 0) 35%,
      rgba(61, 53, 40, 0.016) 35%,
      rgba(61, 53, 40, 0.016) 68%,
      rgba(61, 53, 40, 0) 68%);
}

/* Paper grain, generated, under the text. */
.manifesto .manifesto-sheet::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
  mix-blend-mode: multiply;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'><filter id='p'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' seed='11' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.45  0 0 0 0 0.40  0 0 0 0 0.32  0 0 0 0.16 0'/></filter><rect width='100%' height='100%' filter='url(%23p)'/></svg>");
  background-size: 240px 240px;
}

/* The verse column sits a little left of centre on the sheet, leaving a wide
   left gutter: the margin someone wrote in. */
.manifesto .manifesto-verse {
  position: relative;
  z-index: 1;
  max-width: 27rem;
  margin: 0 auto;
  padding: 0 1.25rem;
}

@media (min-width: 60rem) {
  .manifesto .manifesto-verse {
    margin: 0 0 0 9rem;
    padding: 0;
  }
}

.manifesto .manifesto-title-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* The shared print/web stamp: the same vector as the shirt's front stamp,
   carrying its own rotation and dry-pad marks, so the two cannot drift
   apart. It is banged into the top-right corner, not placed: wider than
   the verse column, its right end runs off the sheet and is cropped by the
   paper (the sheet clips overflow), with air before the first line. */
.manifesto .manifesto-stamp-row {
  display: block;
  margin: 0 0 clamp(2.5rem, 6vh, 4rem);
}

.manifesto .manifesto-stamp {
  display: block;
  width: 104%;
  max-width: none;
  height: auto;
  mix-blend-mode: multiply;
  opacity: 0.92;
}

@media (min-width: 60rem) {
  .manifesto .manifesto-stamp {
    width: 31.5rem;
    margin-left: 4rem;
  }
}

.manifesto p {
  position: relative;
  z-index: 1;
  font-family: var(--manifesto-serif);
  font-size: clamp(1.15rem, 1.05rem + 0.5vw, 1.35rem);
  line-height: 1.55;
  margin: 0 0 2.4rem;
}

.manifesto-carries span {
  display: block;
  padding-left: 1.5em;
}

/* The one thing written by hand: pen, not print, a little off level,
   trespassing into the gutter on a wide screen. */
.manifesto .manifesto-margin {
  font-family: var(--manifesto-pen), 'Bradley Hand', 'Segoe Script', cursive;
  font-style: normal;
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--manifesto-pen-ink);
  transform: rotate(-2.5deg);
  transform-origin: left center;
  max-width: 16rem;
}

@media (min-width: 60rem) {
  .manifesto .manifesto-margin {
    margin-left: -8.5rem;
    max-width: 8.5rem;
    font-size: 0.9rem;
    line-height: 1.6;
  }
}

.manifesto .manifesto-close {
  font-family: var(--font-sans);
  font-size: clamp(1.4rem, 1.2rem + 0.8vw, 1.75rem);
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-top: 3.5rem;
  margin-bottom: 0;
}

/* Human evidence, part one: a glass base is 7–8 cm, about half the width of
   a sheet this size. One ring, broken, slightly off round, set down half off
   the paper's right edge mid-page, well away from the opening stanza. A
   second, much fainter, mostly off the paper near the foot: another evening. */
.manifesto-stains {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  color: var(--manifesto-wine);
  mix-blend-mode: multiply;
}

.manifesto-stains .stain {
  position: absolute;
  display: block;
}

.manifesto-stains .stain-one {
  top: 46%;
  right: 0;
  width: clamp(220px, 64vw, 300px);
  opacity: 0.45;
  transform: translateX(46%);
}

.manifesto-stains .stain-two {
  bottom: -6%;
  left: 0;
  width: clamp(200px, 56vw, 260px);
  opacity: 0.2;
  transform: translateX(-58%);
}

.manifesto-stains .stain-ring {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

/* The four foundations on About: a definition list so the labels are
   navigable, styled to read as run-in paragraph leads. */
.prose dl.foundations {
  margin-bottom: 1.5rem;
}

.prose dl.foundations > div {
  font-size: 1.05rem;
  line-height: 1.75;
  color: var(--atlas-text-secondary);
  margin-bottom: 1.5rem;
}

.prose dl.foundations dt {
  display: inline;
  font-weight: 600;
  color: var(--atlas-text);
}

.prose dl.foundations dd {
  display: inline;
  margin: 0;
}

.prose strong {
  font-weight: 600;
  color: var(--atlas-text);
}

.prose em {
  font-style: italic;
}

.prose code {
  background: var(--atlas-card);
  padding: 0.15em 0.4em;
  border-radius: 4px;
  font-size: 0.9em;
}

.prose pre {
  background: var(--atlas-card);
  border: 1px solid var(--atlas-card-stroke);
  border-radius: 8px;
  padding: 1.25rem;
  overflow-x: auto;
  margin-bottom: 1.5rem;
}
